package com.bank.resilience;

import java.util.logging.Logger;

// Trips OPEN after too many consecutive failures, then fails fast.
class CircuitBreaker {
    private static final Logger log = Logger.getLogger(CircuitBreaker.class.getName());

    private final int failureThreshold;
    private int consecutiveFailures = 0;
    private boolean open = false;

    CircuitBreaker(int failureThreshold) {
        this.failureThreshold = failureThreshold;
    }

    boolean isOpen() { return open; }

    void recordSuccess() {
        consecutiveFailures = 0;
        if (open) {
            open = false;
            log.info("Circuit breaker CLOSED again — downstream recovered");
        }
    }

    void recordFailure() {
        consecutiveFailures++;
        if (consecutiveFailures >= failureThreshold && !open) {
            open = true;
            log.warning(() -> "Circuit breaker OPEN after " + consecutiveFailures + " failures");
        }
    }
}
