package com.bank.resilience;

import java.math.BigDecimal;

// Simulates an unreliable downstream: fails the first few calls, then recovers.
class FlakyAccountService {
    private int callCount = 0;
    private final int failUntilCall;

    FlakyAccountService(int failUntilCall) {
        this.failUntilCall = failUntilCall;
    }

    void applyTransfer(Account from, Account to, BigDecimal amount) {
        callCount++;
        if (callCount <= failUntilCall) {
            throw new RuntimeException("Downstream timeout on call " + callCount);
        }
        from.debit(amount);
        to.credit(amount);
    }
}
