package com.bank.resilience;

import java.math.BigDecimal;
import java.util.logging.Level;
import java.util.logging.Logger;

// Wraps a flaky downstream with a circuit breaker + retry-with-backoff.
class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());

    private final FlakyAccountService downstream;
    private final CircuitBreaker breaker;
    private final int maxRetries;

    int shortCircuitedCount = 0;  // metrics that back the STAR story

    TransferService(FlakyAccountService downstream, CircuitBreaker breaker, int maxRetries) {
        this.downstream = downstream;
        this.breaker = breaker;
        this.maxRetries = maxRetries;
    }

    void transfer(Account from, Account to, BigDecimal amount) {
        if (breaker.isOpen()) {
            shortCircuitedCount++;
            log.warning(() -> "Fail fast — breaker OPEN, skipping transfer of Rs." + amount);
            return;
        }
        for (int attempt = 1; attempt <= maxRetries; attempt++) {
            try {
                downstream.applyTransfer(from, to, amount);
                breaker.recordSuccess();
                final int done = attempt;
                log.info(() -> "Transfer Rs." + amount + " " + from.getAccountId()
                        + " to " + to.getAccountId() + " succeeded on attempt " + done);
                return;
            } catch (RuntimeException ex) {
                breaker.recordFailure();
                log.log(Level.SEVERE, "Attempt " + attempt + " failed", ex);
                sleepBackoff(attempt);
            }
        }
        log.severe(() -> "Transfer of Rs." + amount + " gave up after " + maxRetries + " retries");
    }

    private void sleepBackoff(int attempt) {
        try {
            Thread.sleep(50L * attempt);  // growing delay: 50ms, 100ms, 150ms
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}
