package com.bank.resilience;

import java.math.BigDecimal;
import java.util.logging.Logger;

public class BehavioralDemo {
    private static final Logger log = Logger.getLogger(BehavioralDemo.class.getName());

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya",  new BigDecimal("250000"));

        // Downstream fails the first 2 calls, then recovers (transient blip).
        FlakyAccountService downstream = new FlakyAccountService(2);
        CircuitBreaker breaker = new CircuitBreaker(5);
        TransferService service = new TransferService(downstream, breaker, 3);

        BigDecimal rentAmount = new BigDecimal("50000");
        int totalTransfers = 1;
        for (int i = 0; i < totalTransfers; i++) {
            service.transfer(rajesh, priya, rentAmount);
        }

        log.info(() -> "Rajesh balance: Rs." + rajesh.getBalance());
        log.info(() -> "Priya balance: Rs." + priya.getBalance());
        log.info(() -> "Short-circuited transfers: " + service.shortCircuitedCount);
    }
}
